  'cover':{term:'Cobertura',def:'Quedarte unos pasos detrás de un compañero que va al balón, listo para ayudar si lo superan.'},
  'defensive-midfielder':{term:'Mediocampista defensivo',def:'Un mediocampista que juega delante de los defensas y protege el centro de la cancha.'},
  'direct-free-kick':{term:'Tiro libre directo',def:'Un tiro libre con el que se puede anotar directamente en el arco.'},
  'dribble':{term:'Regate',def:'Avanzar con el balón pegado al pie, con toques pequeños.'},
  'drop-ball':{term:'Balón a tierra',def:'Una reanudación en la que el árbitro deja caer el balón para un jugador, después de detener el juego por algo que no fue falta.'},
  'extra-time':{term:'Tiempo extra',def:'Dos periodos más, de no más de 15 minutos cada uno, que se juegan cuando un partido de copa está empatado y necesita un ganador. En muchos países también se le llama prórroga.'},
  'far-post':{term:'Segundo palo',def:'El poste más lejos del balón. Una carrera al segundo palo llega allí cuando un centro o un pase cruza frente al arco.'},
