  'fixo':{term:'Cierre',def:'El jugador de campo más retrasado en futsal, que defiende primero y empieza los ataques.'},
  'formation':{term:'Formación',def:'Cómo se acomoda un equipo, escrito con números de atrás hacia adelante, como 2-3-1 o 4-3-3.'},
