  'pitch':{term:'Campo (pitch)',def:'Otra palabra para la cancha de fútbol. Se usa más en España, y en Gran Bretaña dicen pitch.'},
  'pivot':{term:'Pívot',def:'El delantero en futsal, que muchas veces recibe de espaldas al arco y luego gira o descarga el balón.'},
