  'rest-defense':{term:'Equilibrio defensivo',def:'Los jugadores que un equipo deja detrás del balón mientras ataca, para frenar un contraataque.'},
  'save':{term:'Atajada',def:'Cuando el portero evita que un tiro entre al arco.'},
  'scanning':{term:'Mirar por encima del hombro',def:'Mirar alrededor antes de que llegue el balón, para saber dónde están tus compañeros y los rivales.'},
