  'stoppage-time':{term:'Tiempo añadido',def:'Tiempo que el árbitro agrega al final de un tiempo por cambios, lesiones y otras demoras. También se llama tiempo de reposición o de descuento.'},
  'striker':{term:'Delantero',def:'El atacante que juega más cerca del arco del otro equipo.'},
  'substitute':{term:'Suplente',def:'Un jugador que empieza en la banca y entra por un compañero.'},
  'support':{term:'Apoyo',def:'Moverte adonde el compañero con el balón te pueda pasar, saliendo de detrás de un defensa.'},
  'throw-in':{term:'Saque de banda',def:'El saque con las manos que reanuda el juego cuando el balón cruza la línea de banda: con las dos manos, desde atrás y por encima de la cabeza.'},
  'touchline':{term:'Línea de banda',def:'La línea larga a cada lado de la cancha. También se le dice línea lateral.'},
