  'var':{term:'VAR',def:'El árbitro asistente de video: un oficial que mira repeticiones y puede pedirle al árbitro que revise goles, decisiones de penal, rojas directas y una tarjeta mostrada al jugador equivocado.'},
  'wall':{term:'Barrera',def:'Una fila de defensas parados a 10 yardas de un tiro libre para tapar el tiro.'},
