  'wingback':{term:'Carrilero',def:'Un jugador de banda que defiende como un lateral y ataca como un extremo.'},
  'winger':{term:'Extremo',def:'Un atacante que juega cerca de la línea de banda.'},
  'yellow-card':{term:'Tarjeta amarilla',def:'Una advertencia del árbitro. Dos en un partido son una roja.'},
  'give-and-go':{term:'Pared',def:'Pasa a un compañero, deja atrás a tu marcador y recibe el balón de vuelta enseguida. También se llama uno-dos o toco y me voy.'},
  'third-man-run':{term:'Tercer hombre',def:'La carrera de un tercer jugador que recibe después de que dos compañeros se pasan el balón. Llega a un jugador que el primer pasador no podía encontrar directo.'},
  'overlap':{term:'Desdoble',def:'Una carrera por fuera del compañero que tiene el balón, para hacer dos atacantes contra un defensa por un lado de la cancha.'},
  'through-ball':{term:'Pase al hueco',def:'Un pase entre los defensas o detrás de ellos, al espacio, para que un compañero llegue corriendo.'},
  'switching-play':{term:'Cambio de juego',def:'Mover el balón del lado lleno de jugadores al lado libre de la cancha.'},
  'two-v-one':{term:'2v1 (dos contra uno)',def:'Dos atacantes contra un defensa. El que tiene el balón conduce hacia el defensa: pasa si el defensa sale, y sigue si no sale.'},
  'cutback':{term:'Centro atrás',def:'Un pase desde cerca de la línea de meta, hacia atrás, para un compañero que llega frente al arco.'},
