  'marking':{term:'Marca',def:'Quedarte cerca de un rival, entre él y tu arco, para que no pueda recibir el balón fácilmente.'},
  'goal-side':{term:'Lado del arco (goal-side)',def:'Ponerte entre un atacante y tu propio arco.'},
  'tackle':{term:'Entrada',def:'Usar el pie para quitarle el balón a un rival.'},
  'counterattack':{term:'Contraataque',def:'Un ataque rápido justo después de recuperar el balón, antes de que el otro equipo pueda reorganizarse.'},
